class Wallet {
  constructor(public balanceKobo: number) {}
  withdraw(amountKobo: number): void {
    if (amountKobo > this.balanceKobo) throw new RangeError("insufficient funds");
    this.balanceKobo -= amountKobo;
  }
}

class SavingsWallet extends Wallet {
  override withdraw(amountKobo: number): void {
    if (amountKobo > 5_000_000) throw new RangeError("limit is ₦50,000");
    super.withdraw(amountKobo);
  }
}

function emptyInto(from: Wallet, to: Wallet): void {
  const amount = from.balanceKobo;
  from.withdraw(amount);
  to.balanceKobo += amount;
}

const results: string[] = [];
for (const from of [new Wallet(8_000_000), new SavingsWallet(8_000_000)]) {
  const to = new Wallet(0);
  try {
    emptyInto(from, to);
    results.push(`moved ${to.balanceKobo}`);
  } catch (error) {
    results.push(String(error));
  }
}
console.log(results.join(" | "));

interface Channel {
  send(text: string): string;
}

let smsFailures = 1;
const sms: Channel = {
  send(text) {
    if (smsFailures-- > 0) throw new Error("timeout");
    return `sms:${text}`;
  },
};
const email: Channel = { send: (text) => `email:${text}` };

function withRetry(channel: Channel, attempts: number): Channel {
  return {
    send(text) {
      for (let attempt = 1; ; attempt++) {
        try {
          return channel.send(text);
        } catch (error) {
          if (attempt >= attempts) throw error;
        }
      }
    },
  };
}

function withFallback(primary: Channel, backup: Channel): Channel {
  return {
    send(text) {
      try {
        return primary.send(text);
      } catch {
        return backup.send(text);
      }
    },
  };
}

const once = withFallback(sms, email);
smsFailures = 1;
const retried = withFallback(withRetry(sms, 2), email);
console.log(once.send("A"), once.send("B"));
smsFailures = 1;
console.log(retried.send("C"));

