function providerContract(provider: PaymentProvider): string[] {
  const failures: string[] = [];
  for (const amount of [100, 250_000, 50_000_000]) {
    const fee = provider.feeKobo(amount);
    if (!Number.isInteger(fee) || fee < 0 || fee >= amount) failures.push(`fee for ${amount} is ${fee}`);
  }
  return failures;
}

