interface WalletData {
  readonly owner: string;
  readonly balanceKobo: number;
}

class Wallet {
  #balanceKobo: number;
  constructor(readonly owner: string, balanceKobo = 0) {
    this.#balanceKobo = balanceKobo;
  }
  get balanceKobo(): number {
    return this.#balanceKobo;
  }
  toData(): WalletData {
    return { owner: this.owner, balanceKobo: this.#balanceKobo };
  }
  static fromData(data: WalletData): Wallet {
    if (!Number.isInteger(data.balanceKobo) || data.balanceKobo < 0) throw new RangeError("invalid balance");
    return new Wallet(data.owner, data.balanceKobo);
  }
}

const json = JSON.stringify(new Wallet("Ada", 250_000).toData());
console.log(json);
console.log(Wallet.fromData(JSON.parse(json)).balanceKobo);
try {
  Wallet.fromData({ owner: "Mallory", balanceKobo: -1 });
} catch (error) {
  console.log(String(error));
}
